import 'package:flutter/material.dart';
import 'package:syncfusion_flutter_charts/charts.dart';

// 데이터 모델
class SalesData {
  final String month;
  final double sales;

  SalesData(this.month, this.sales);
}

class LineChartExample extends StatelessWidget {
  const LineChartExample({super.key});

  @override
  Widget build(BuildContext context) {
    // 샘플 데이터
    final List<SalesData> chartData = [
      SalesData('1월', 35),
      SalesData('2월', 28),
      SalesData('3월', 34),
      SalesData('4월', 32),
      SalesData('5월', 40),
      SalesData('6월', 45),
    ];

    return Scaffold(
      appBar: AppBar(title: const Text('라인 차트')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: SfCartesianChart(
          // 차트 제목
          title: const ChartTitle(text: '월별 판매량'),

          // 범례 표시
          legend: const Legend(isVisible: true),

          // 툴팁 활성화
          tooltipBehavior: TooltipBehavior(enable: true),

          // X축 설정
          primaryXAxis: const CategoryAxis(
            title: AxisTitle(text: '월'),
          ),

          // Y축 설정
          primaryYAxis: const NumericAxis(
            title: AxisTitle(text: '판매량'),
            minimum: 0,
            maximum: 50,
            interval: 10,
          ),

          // 데이터 시리즈
          series: <CartesianSeries<SalesData, String>>[
            LineSeries<SalesData, String>(
              name: '판매량',
              dataSource: chartData,
              xValueMapper: (SalesData data, _) => data.month,
              yValueMapper: (SalesData data, _) => data.sales,
              // 데이터 포인트 표시
              markerSettings: const MarkerSettings(isVisible: true),
              // 데이터 라벨 표시
              dataLabelSettings: const DataLabelSettings(isVisible: true),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:syncfusion_flutter_charts/charts.dart';

class ProductData {
  final String product;
  final double sales2023;
  final double sales2024;

  ProductData(this.product, this.sales2023, this.sales2024);
}

class BarChartExample extends StatelessWidget {
  const BarChartExample({super.key});

  @override
  Widget build(BuildContext context) {
    final List<ProductData> data = [
      ProductData('제품A', 120, 150),
      ProductData('제품B', 90, 110),
      ProductData('제품C', 75, 95),
      ProductData('제품D', 60, 80),
    ];

    return Scaffold(
      appBar: AppBar(title: const Text('바 차트')),
      body: Column(
        children: [
          // 세로 바 차트 (Column)
          Expanded(
            child: SfCartesianChart(
              title: const ChartTitle(text: '연도별 제품 판매량'),
              legend: const Legend(
                isVisible: true,
                position: LegendPosition.bottom,
              ),
              tooltipBehavior: TooltipBehavior(enable: true),
              primaryXAxis: const CategoryAxis(),
              primaryYAxis: const NumericAxis(
                title: AxisTitle(text: '판매량 (억원)'),
              ),
              series: <CartesianSeries>[
                // 2023년 바
                ColumnSeries<ProductData, String>(
                  name: '2023년',
                  dataSource: data,
                  xValueMapper: (d, _) => d.product,
                  yValueMapper: (d, _) => d.sales2023,
                  color: Colors.blue,
                ),
                // 2024년 바
                ColumnSeries<ProductData, String>(
                  name: '2024년',
                  dataSource: data,
                  xValueMapper: (d, _) => d.product,
                  yValueMapper: (d, _) => d.sales2024,
                  color: Colors.orange,
                ),
              ],
            ),
          ),

          // 가로 바 차트 (Bar)
          Expanded(
            child: SfCartesianChart(
              title: const ChartTitle(text: '가로 바 차트'),
              primaryXAxis: const CategoryAxis(),
              primaryYAxis: const NumericAxis(),
              series: <CartesianSeries>[
                BarSeries<ProductData, String>(
                  dataSource: data,
                  xValueMapper: (d, _) => d.product,
                  yValueMapper: (d, _) => d.sales2024,
                  // 그라데이션 효과
                  gradient: const LinearGradient(
                    colors: [Colors.blue, Colors.purple],
                  ),
                  // 라운드 모서리
                  borderRadius: const BorderRadius.all(Radius.circular(8)),
                  dataLabelSettings: const DataLabelSettings(isVisible: true),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

// 스택 바 차트
class StackedBarExample extends StatelessWidget {
  const StackedBarExample({super.key});

  @override
  Widget build(BuildContext context) {
    final data = [
      ProductData('Q1', 30, 20),
      ProductData('Q2', 35, 25),
      ProductData('Q3', 40, 30),
      ProductData('Q4', 45, 35),
    ];

    return SfCartesianChart(
      title: const ChartTitle(text: '분기별 매출 (스택)'),
      legend: const Legend(isVisible: true),
      series: <CartesianSeries>[
        StackedColumnSeries<ProductData, String>(
          name: '온라인',
          dataSource: data,
          xValueMapper: (d, _) => d.product,
          yValueMapper: (d, _) => d.sales2023,
        ),
        StackedColumnSeries<ProductData, String>(
          name: '오프라인',
          dataSource: data,
          xValueMapper: (d, _) => d.product,
          yValueMapper: (d, _) => d.sales2024,
        ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:syncfusion_flutter_charts/charts.dart';

class CategoryData {
  final String category;
  final double value;
  final Color color;

  CategoryData(this.category, this.value, this.color);
}

class PieChartExample extends StatelessWidget {
  const PieChartExample({super.key});

  @override
  Widget build(BuildContext context) {
    final List<CategoryData> data = [
      CategoryData('식비', 35, Colors.red),
      CategoryData('교통', 20, Colors.blue),
      CategoryData('쇼핑', 25, Colors.green),
      CategoryData('문화', 12, Colors.orange),
      CategoryData('기타', 8, Colors.purple),
    ];

    return Scaffold(
      appBar: AppBar(title: const Text('원형 차트')),
      body: Column(
        children: [
          // 기본 파이 차트
          Expanded(
            child: SfCircularChart(
              title: const ChartTitle(text: '지출 비율'),
              legend: const Legend(
                isVisible: true,
                position: LegendPosition.bottom,
                overflowMode: LegendItemOverflowMode.wrap,
              ),
              tooltipBehavior: TooltipBehavior(enable: true),
              series: <CircularSeries>[
                PieSeries<CategoryData, String>(
                  dataSource: data,
                  xValueMapper: (d, _) => d.category,
                  yValueMapper: (d, _) => d.value,
                  pointColorMapper: (d, _) => d.color,
                  // 데이터 라벨
                  dataLabelSettings: const DataLabelSettings(
                    isVisible: true,
                    labelPosition: ChartDataLabelPosition.outside,
                  ),
                  // 조각 분리 효과
                  explode: true,
                  explodeIndex: 0,  // 첫 번째 조각 분리
                ),
              ],
            ),
          ),

          // 도넛 차트
          Expanded(
            child: SfCircularChart(
              title: const ChartTitle(text: '도넛 차트'),
              legend: const Legend(isVisible: true),
              annotations: <CircularChartAnnotation>[
                // 중앙에 텍스트 추가
                CircularChartAnnotation(
                  widget: const Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        '총 지출',
                        style: TextStyle(fontSize: 12, color: Colors.grey),
                      ),
                      Text(
                        '₩100만',
                        style: TextStyle(
                          fontSize: 20,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
              series: <CircularSeries>[
                DoughnutSeries<CategoryData, String>(
                  dataSource: data,
                  xValueMapper: (d, _) => d.category,
                  yValueMapper: (d, _) => d.value,
                  pointColorMapper: (d, _) => d.color,
                  // 도넛 두께
                  innerRadius: '60%',
                  radius: '80%',
                  // 라벨
                  dataLabelMapper: (d, _) => '${d.value.toInt()}%',
                  dataLabelSettings: const DataLabelSettings(
                    isVisible: true,
                    textStyle: TextStyle(fontSize: 12),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

// 반원 도넛 (게이지 스타일)
class SemiDoughnutExample extends StatelessWidget {
  const SemiDoughnutExample({super.key});

  @override
  Widget build(BuildContext context) {
    return SfCircularChart(
      series: <CircularSeries>[
        DoughnutSeries<CategoryData, String>(
          dataSource: [
            CategoryData('완료', 75, Colors.green),
            CategoryData('남음', 25, Colors.grey.shade300),
          ],
          xValueMapper: (d, _) => d.category,
          yValueMapper: (d, _) => d.value,
          pointColorMapper: (d, _) => d.color,
          innerRadius: '70%',
          // 반원으로 표시
          startAngle: 180,
          endAngle: 360,
        ),
      ],
      annotations: <CircularChartAnnotation>[
        CircularChartAnnotation(
          angle: 270,
          radius: '0%',
          widget: const Text(
            '75%',
            style: TextStyle(fontSize: 32, fontWeight: FontWeight.bold),
          ),
        ),
      ],
    );
  }
}

import 'dart:async';
import 'dart:math';
import 'package:flutter/material.dart';
import 'package:syncfusion_flutter_charts/charts.dart';

class LiveData {
  final DateTime time;
  final double value;

  LiveData(this.time, this.value);
}

class InteractiveChartExample extends StatefulWidget {
  const InteractiveChartExample({super.key});

  @override
  State<InteractiveChartExample> createState() => _InteractiveChartExampleState();
}

class _InteractiveChartExampleState extends State<InteractiveChartExample> {
  late List<LiveData> _chartData;
  late Timer _timer;
  final Random _random = Random();
  ChartSeriesController? _chartSeriesController;

  @override
  void initState() {
    super.initState();
    _chartData = _generateInitialData();
    // 1초마다 데이터 업데이트
    _timer = Timer.periodic(const Duration(seconds: 1), _updateData);
  }

  List<LiveData> _generateInitialData() {
    final now = DateTime.now();
    return List.generate(20, (index) {
      return LiveData(
        now.subtract(Duration(seconds: 20 - index)),
        50 + _random.nextDouble() * 50,
      );
    });
  }

  void _updateData(Timer timer) {
    setState(() {
      // 새 데이터 추가
      _chartData.add(LiveData(
        DateTime.now(),
        50 + _random.nextDouble() * 50,
      ));
      // 오래된 데이터 제거
      if (_chartData.length > 20) {
        _chartData.removeAt(0);
        // 차트 업데이트 (애니메이션 포함)
        _chartSeriesController?.updateDataSource(
          addedDataIndex: _chartData.length - 1,
          removedDataIndex: 0,
        );
      }
    });
  }

  @override
  void dispose() {
    _timer.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('실시간 차트')),
      body: Column(
        children: [
          // 실시간 라인 차트
          Expanded(
            child: SfCartesianChart(
              title: const ChartTitle(text: '실시간 데이터'),

              // 줌/팬 기능
              zoomPanBehavior: ZoomPanBehavior(
                enablePinching: true,      // 핀치 줌
                enableDoubleTapZooming: true,  // 더블탭 줌
                enablePanning: true,        // 팬(드래그)
                enableSelectionZooming: true,  // 드래그로 영역 줌
                zoomMode: ZoomMode.x,       // X축만 줌
              ),

              // 트랙볼 (마우스오버 시 정보 표시)
              trackballBehavior: TrackballBehavior(
                enable: true,
                activationMode: ActivationMode.singleTap,
                tooltipSettings: const InteractiveTooltip(
                  format: 'point.y',
                ),
              ),

              primaryXAxis: DateTimeAxis(
                intervalType: DateTimeIntervalType.seconds,
                interval: 5,
                dateFormat: DateFormat.Hms(),
              ),

              primaryYAxis: const NumericAxis(
                minimum: 0,
                maximum: 120,
              ),

              series: <CartesianSeries>[
                LineSeries<LiveData, DateTime>(
                  dataSource: _chartData,
                  xValueMapper: (d, _) => d.time,
                  yValueMapper: (d, _) => d.value,
                  // 컨트롤러 연결 (실시간 업데이트용)
                  onRendererCreated: (controller) {
                    _chartSeriesController = controller;
                  },
                  // 영역 채우기
                  color: Colors.blue,
                  width: 2,
                  animationDuration: 0, // 실시간은 애니메이션 비활성화
                ),
              ],
            ),
          ),

          // 선택 가능한 차트
          Expanded(
            child: SfCartesianChart(
              title: const ChartTitle(text: '클릭해서 선택'),

              // 데이터 포인트 선택
              selectionType: SelectionType.point,
              selectionGesture: ActivationMode.singleTap,

              tooltipBehavior: TooltipBehavior(enable: true),

              primaryXAxis: const CategoryAxis(),

              series: <CartesianSeries>[
                ColumnSeries<LiveData, String>(
                  dataSource: [
                    LiveData(DateTime(2024, 1), 80),
                    LiveData(DateTime(2024, 2), 70),
                    LiveData(DateTime(2024, 3), 90),
                    LiveData(DateTime(2024, 4), 85),
                  ],
                  xValueMapper: (d, _) => '${d.time.month}월',
                  yValueMapper: (d, _) => d.value,
                  // 선택 시 스타일
                  selectionBehavior: SelectionBehavior(
                    enable: true,
                    selectedColor: Colors.red,
                    unselectedColor: Colors.grey.shade300,
                  ),
                  // 선택 이벤트
                  onPointTap: (pointDetails) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text('선택: ${pointDetails.pointIndex}번째 데이터'),
                      ),
                    );
                  },
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

